import Link from "next/link";

import { searchProducts } from "@/lib/search";
import type { SearchOffer, SearchResponse } from "@/lib/search/types";

export const dynamic = "force-dynamic";

type PageProps = {
  searchParams: Promise<{
    q?: string;
  }>;
};

const SAMPLE_QUERIES = [
  "iphone 15",
  "playstation 5",
  "air fryer philips walita",
  "monitor gamer 27",
];

const money = new Intl.NumberFormat("pt-BR", {
  style: "currency",
  currency: "BRL",
});

function statusLabel(status: SearchResponse["providers"][number]["status"]) {
  switch (status) {
    case "ok":
      return "Coletando";
    case "empty":
      return "Sem ofertas";
    case "not_configured":
      return "Aguardando pitchlabs";
    case "error":
      return "Falhou";
    default:
      return "Parcial";
  }
}

function statusTone(status: SearchResponse["providers"][number]["status"]) {
  switch (status) {
    case "ok":
      return "border-[var(--emerald-400)]/30 bg-[var(--emerald-400)]/12 text-[var(--emerald-100)]";
    case "not_configured":
      return "border-[var(--amber-400)]/30 bg-[var(--amber-400)]/12 text-[var(--amber-50)]";
    case "error":
      return "border-[var(--rose-400)]/30 bg-[var(--rose-400)]/12 text-[var(--rose-50)]";
    default:
      return "border-white/10 bg-white/8 text-white/72";
  }
}

function offerMeta(offer: SearchOffer) {
  return [
    offer.installments,
    offer.seller ? `Seller ${offer.seller}` : undefined,
    offer.shipping,
  ].filter(Boolean);
}

function ResultCard({ offer, index }: { offer: SearchOffer; index: number }) {
  return (
    <article className="group relative overflow-hidden rounded-[2rem] border border-white/10 bg-[linear-gradient(135deg,rgba(255,255,255,0.1),rgba(255,255,255,0.03))] p-5 shadow-[0_28px_70px_rgba(0,0,0,0.24)] backdrop-blur-sm transition duration-300 hover:-translate-y-1 hover:border-[var(--accent-300)]/40 hover:shadow-[0_36px_90px_rgba(0,0,0,0.3)]">
      <div className="absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,rgba(255,255,255,0.5),transparent)]" />
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="font-mono text-xs uppercase tracking-[0.28em] text-[var(--accent-200)]/70">
            #{String(index + 1).padStart(2, "0")} • {offer.storeName}
          </p>
          <h2 className="mt-3 max-w-3xl font-display text-2xl font-semibold leading-tight text-white">
            {offer.title}
          </h2>
        </div>
        <span className="rounded-full border border-white/10 bg-black/20 px-3 py-1 font-mono text-[11px] uppercase tracking-[0.22em] text-white/55">
          {offer.source}
        </span>
      </div>

      <div className="mt-6 flex flex-col gap-5 md:flex-row md:items-end md:justify-between">
        <div>
          <p className="font-mono text-xs uppercase tracking-[0.28em] text-white/45">
            Melhor preço capturado
          </p>
          <p className="mt-2 font-display text-4xl font-semibold text-[var(--sand-50)]">
            {money.format(offer.price)}
          </p>
        </div>

        <div className="flex flex-wrap gap-2 text-sm text-white/65">
          {offerMeta(offer).map((entry) => (
            <span
              key={entry}
              className="rounded-full border border-white/10 bg-white/6 px-3 py-1.5"
            >
              {entry}
            </span>
          ))}
        </div>
      </div>

      <div className="mt-6 flex flex-wrap items-center gap-3">
        <a
          href={offer.url}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-2 rounded-full bg-[var(--accent-300)] px-4 py-2.5 font-mono text-xs uppercase tracking-[0.22em] text-[var(--ink-950)] transition hover:bg-[var(--accent-200)]"
        >
          Abrir oferta
        </a>
        {offer.image ? (
          <a
            href={offer.image}
            target="_blank"
            rel="noreferrer"
            className="inline-flex items-center gap-2 rounded-full border border-white/10 px-4 py-2.5 font-mono text-xs uppercase tracking-[0.22em] text-white/60 transition hover:border-white/20 hover:text-white"
          >
            Ver imagem
          </a>
        ) : null}
      </div>
    </article>
  );
}

function Sidebar({ results }: { results: SearchResponse | null }) {
  if (!results) {
    return (
      <aside className="rounded-[2rem] border border-white/10 bg-black/20 p-6 backdrop-blur-sm">
        <p className="font-mono text-xs uppercase tracking-[0.28em] text-[var(--accent-200)]/65">
          Radar pronto
        </p>
        <h2 className="mt-3 font-display text-3xl text-white">
          Digite um produto para comparar.
        </h2>
        <p className="mt-4 text-sm leading-7 text-white/68">
          O app consulta Amazon, Mercado Livre, KaBuM, Americanas e um slot
          dedicado ao pitchlabs para lojas mais protegidas.
        </p>
      </aside>
    );
  }

  return (
    <aside className="space-y-5">
      <section className="rounded-[2rem] border border-white/10 bg-black/20 p-6 backdrop-blur-sm">
        <p className="font-mono text-xs uppercase tracking-[0.28em] text-[var(--accent-200)]/65">
          Resumo
        </p>
        <div className="mt-4 grid gap-4 md:grid-cols-3 xl:grid-cols-1">
          <div>
            <p className="font-mono text-[11px] uppercase tracking-[0.24em] text-white/42">
              Query
            </p>
            <p className="mt-2 text-lg text-white">{results.query}</p>
          </div>
          <div>
            <p className="font-mono text-[11px] uppercase tracking-[0.24em] text-white/42">
              Ofertas
            </p>
            <p className="mt-2 text-3xl font-display text-[var(--sand-50)]">
              {results.offers.length}
            </p>
          </div>
          <div>
            <p className="font-mono text-[11px] uppercase tracking-[0.24em] text-white/42">
              Melhor
            </p>
            <p className="mt-2 text-3xl font-display text-[var(--sand-50)]">
              {results.offers[0] ? money.format(results.offers[0].price) : "n/a"}
            </p>
          </div>
        </div>
      </section>

      <section className="rounded-[2rem] border border-white/10 bg-black/20 p-6 backdrop-blur-sm">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="font-mono text-xs uppercase tracking-[0.28em] text-[var(--accent-200)]/65">
              Fontes
            </p>
            <h2 className="mt-2 font-display text-2xl text-white">
              Estado dos coletores
            </h2>
          </div>
        </div>

        <div className="mt-5 space-y-3">
          {results.providers.map((provider) => (
            <article
              key={provider.storeKey}
              className="rounded-[1.5rem] border border-white/10 bg-white/5 p-4"
            >
              <div className="flex items-start justify-between gap-3">
                <div>
                  <p className="font-mono text-xs uppercase tracking-[0.22em] text-white/42">
                    {provider.storeName}
                  </p>
                  <p className="mt-2 text-sm text-white/72">
                    {provider.note ?? `${provider.offers.length} ofertas válidas.`}
                  </p>
                </div>
                <span
                  className={`rounded-full border px-3 py-1 font-mono text-[10px] uppercase tracking-[0.18em] ${statusTone(provider.status)}`}
                >
                  {statusLabel(provider.status)}
                </span>
              </div>
              <p className="mt-3 font-mono text-[11px] uppercase tracking-[0.18em] text-white/38">
                {provider.offers.length} resultados • {provider.latencyMs} ms
              </p>
            </article>
          ))}
        </div>
      </section>
    </aside>
  );
}

export default async function Home({ searchParams }: PageProps) {

import { amazonAdapter } from "@/lib/search/adapters/amazon";
import { americanasAdapter } from "@/lib/search/adapters/americanas";
import { kabumAdapter } from "@/lib/search/adapters/kabum";
import { mercadoLivreAdapter } from "@/lib/search/adapters/mercado-livre";
import { pitchlabsAdapter } from "@/lib/search/adapters/pitchlabs";
import type { SearchResponse, StoreAdapter } from "@/lib/search/types";

const ADAPTERS: StoreAdapter[] = [
  mercadoLivreAdapter,
  amazonAdapter,
  kabumAdapter,
  americanasAdapter,
  pitchlabsAdapter,
];

export async function searchProducts(query: string): Promise<SearchResponse> {
  const providers = await Promise.all(ADAPTERS.map((adapter) => adapter.search(query)));
  const offers = providers.flatMap((provider) => provider.offers).sort((a, b) => a.price - b.price);

  return {
    query,
    generatedAt: new Date().toISOString(),
    offers,
    providers,
  };
}

import { NextRequest, NextResponse } from "next/server";

import { searchProducts } from "@/lib/search";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const query = request.nextUrl.searchParams.get("q")?.trim();

  if (!query) {
    return NextResponse.json(
      { error: "Missing required search param: q" },
      { status: 400 },
    );
  }

  const results = await searchProducts(query);
  return NextResponse.json(results);
}

