import type { ResearchSource } from "@/lib/travel/types";

const OPENAI_API_URL = "https://api.openai.com/v1/responses";

type StructuredResearchParams = {
  prompt: string;
  schemaName: string;
  schema: Record<string, unknown>;
};

type StructuredResearchResult<T> = {
  data: T;
  sources: ResearchSource[];
};

function getApiKey() {
  return process.env.OPEN_AI_KEY ?? process.env.OPENAI_API_KEY ?? "";
}

function getModel() {
  return process.env.OPENAI_MODEL ?? "gpt-5-mini";
}

function findResponseText(payload: Record<string, unknown>) {
  if (typeof payload.output_text === "string" && payload.output_text.trim()) {
    return payload.output_text.trim();
  }

  const output = Array.isArray(payload.output) ? payload.output : [];

  for (const item of output) {
    if (!item || typeof item !== "object") {
      continue;
    }

    const message = item as {
      type?: string;
      content?: Array<{ text?: string }>;
    };

    if (message.type !== "message" || !Array.isArray(message.content)) {
      continue;
    }

    for (const contentItem of message.content) {
      if (typeof contentItem?.text === "string" && contentItem.text.trim()) {
        return contentItem.text.trim();
      }
    }
  }

  return "";
}

function safeDomain(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

function extractSources(payload: Record<string, unknown>): ResearchSource[] {
  const seen = new Map<string, ResearchSource>();
  const output = Array.isArray(payload.output) ? payload.output : [];

  const addSource = (raw: unknown) => {
    if (!raw || typeof raw !== "object") {
      return;
    }

    const source = raw as {
      title?: unknown;
      url?: unknown;
    };

    if (typeof source.url !== "string" || !source.url) {
      return;
    }

    if (seen.has(source.url)) {
      return;
    }

    seen.set(source.url, {
      title:
        typeof source.title === "string" && source.title.trim()
          ? source.title.trim()
          : safeDomain(source.url),
      url: source.url,
      domain: safeDomain(source.url),
    });
  };

  for (const item of output) {
    if (!item || typeof item !== "object") {
      continue;
    }

    const searchCall = item as {
      action?: { sources?: unknown[] };
      sources?: unknown[];
      content?: Array<{ annotations?: unknown[] }>;
    };

    if (Array.isArray(searchCall.action?.sources)) {
      searchCall.action.sources.forEach(addSource);
    }

    if (Array.isArray(searchCall.sources)) {
      searchCall.sources.forEach(addSource);
    }

    if (Array.isArray(searchCall.content)) {
      for (const contentItem of searchCall.content) {
        if (!Array.isArray(contentItem?.annotations)) {
          continue;
        }

        for (const annotation of contentItem.annotations) {
          addSource(annotation);
        }
      }
    }
  }

  return Array.from(seen.values());
}

export function hasTravelResearchAccess() {
  return Boolean(getApiKey());
}

export async function runStructuredWebResearch<T>({
  prompt,
  schemaName,
  schema,
}: StructuredResearchParams): Promise<StructuredResearchResult<T>> {
  const apiKey = getApiKey();

  if (!apiKey) {
    throw new Error("Missing OPEN_AI_KEY or OPENAI_API_KEY.");
  }

  const response = await fetch(OPENAI_API_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${apiKey}`,
    },
    signal: AbortSignal.timeout(90_000),
    body: JSON.stringify({
      model: getModel(),
      input: prompt,
      include: ["web_search_call.action.sources"],
      max_output_tokens: 2200,
      tools: [
        {
          type: "web_search",
          search_context_size: "high",
        },
      ],
      text: {
        format: {
          type: "json_schema",
          name: schemaName,
          strict: true,
          schema,
        },
      },
    }),
  });

  const payload = (await response.json()) as Record<string, unknown>;

  if (!response.ok) {
    const message =
      typeof payload.error === "object" &&
      payload.error &&
      "message" in payload.error &&
      typeof payload.error.message === "string"
        ? payload.error.message
        : `OpenAI request failed with HTTP ${response.status}.`;

    throw new Error(message);
  }

  const rawText = findResponseText(payload);

  if (!rawText) {
    throw new Error("OpenAI returned no structured text.");
  }

  let data: T;

  try {
    data = JSON.parse(rawText) as T;
  } catch (error) {
    throw new Error(
      error instanceof Error
        ? `Failed to parse OpenAI JSON: ${error.message}`
        : "Failed to parse OpenAI JSON.",
    );
  }

  return {
    data,
    sources: extractSources(payload),
  };
}

