import type { Metadata } from "next";
import { IBM_Plex_Mono, IBM_Plex_Sans, Newsreader } from "next/font/google";

import "./globals.css";

const bodyFont = IBM_Plex_Sans({
  subsets: ["latin"],
  variable: "--font-body",
  weight: ["400", "500", "600", "700"],
});

const monoFont = IBM_Plex_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
  weight: ["400", "500"],
});

const displayFont = Newsreader({
  subsets: ["latin"],
  variable: "--font-display",
  weight: ["500", "600", "700"],
});

export const metadata: Metadata = {
  title: "Price Trip",
  description:
    "Compare Brazilian product prices and research better ticket and housing windows for a trip.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="pt-BR">
      <body
        className={`${bodyFont.variable} ${monoFont.variable} ${displayFont.variable} min-h-screen antialiased`}
      >
        {children}
      </body>
    </html>
  );
}

@import "tailwindcss";

:root {
  --background: #061017;
  --foreground: #f8f3eb;
  --surface: rgba(11, 23, 31, 0.74);
  --surface-strong: rgba(6, 17, 24, 0.94);
  --ink-950: #041018;
  --sand-50: #fffaf1;
  --sea-50: #ecfeff;
  --sea-100: #cffafe;
  --sea-200: #a5f3fc;
  --sea-300: #67e8f9;
  --sea-400: #22d3ee;
  --sea-500: #06b6d4;
  --sea-600: #0891b2;
  --sea-700: #0e7490;
  --sea-800: #155e75;
  --sea-900: #164e63;
  --sea-950: #082f49;
  --sun-100: #fef3c7;
  --sun-300: #fcd34d;
  --sun-400: #f59e0b;
  --sun-500: #d97706;
  --emerald-100: #dcfce7;
  --emerald-400: #34d399;
  --rose-50: #fff1f2;
  --rose-400: #fb7185;
  --line: rgba(236, 254, 255, 0.12);
  --line-strong: rgba(236, 254, 255, 0.22);
  --muted: rgba(248, 243, 235, 0.66);
  --muted-strong: rgba(248, 243, 235, 0.82);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-body);
  --font-mono: var(--font-mono);
  --font-display: var(--font-display);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  background:
    radial-gradient(circle at top, rgba(103, 232, 249, 0.08), transparent 28%),
    linear-gradient(180deg, #0d1b22 0%, #061017 42%, #040a10 100%);
  color: var(--foreground);
  font-family: var(--font-body), sans-serif;
  text-rendering: optimizeLegibility;
}

body::before {
  content: "";
  pointer-events: none;
  position: fixed;
  inset: 0;
  background:
    linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
  background-size: 80px 80px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.6), transparent 92%);
}

::selection {
  background: rgba(103, 232, 249, 0.26);
  color: var(--sand-50);
}

a,
button,
input,
textarea {
  transition:
    color 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}

strong {
  font-weight: 600;
}

.panel-shell {
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255, 250, 241, 0.06), transparent 35%),
    var(--surface);
  box-shadow:
    0 24px 80px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(18px);
}

.panel-muted {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent), rgba(2, 9, 14, 0.54);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(14px);
}

.lane-card {
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at top right, rgba(252, 211, 77, 0.12), transparent 32%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02));
}

.lane-card:hover {
  border-color: rgba(103, 232, 249, 0.3);
  transform: translateY(-2px);
}

.eyebrow {
  font-family: var(--font-mono), monospace;
  font-size: 11px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--sea-100);
}

.action-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  padding: 0.8rem 1.1rem;
  font-family: var(--font-mono), monospace;
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--sand-50);
}

.action-pill:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.08);
}

.action-pill-primary {
  border-color: rgba(103, 232, 249, 0.34);
  background: linear-gradient(135deg, rgba(103, 232, 249, 0.94), rgba(252, 211, 77, 0.92));
  color: var(--ink-950);
  box-shadow: 0 14px 30px rgba(103, 232, 249, 0.16);
}

.action-pill-primary:hover {
  background: linear-gradient(135deg, rgba(165, 243, 252, 0.98), rgba(253, 224, 71, 0.94));
}

.field-input {
  width: 100%;
  border-radius: 1.1rem;
  border: 1px solid var(--line);
  background: rgba(3, 12, 18, 0.78);
  padding: 0.9rem 1rem;
  color: var(--sand-50);
  outline: none;
}

.field-input::placeholder {
  color: rgba(248, 243, 235, 0.35);
}

.field-input:focus {
  border-color: rgba(103, 232, 249, 0.45);
  box-shadow: 0 0 0 3px rgba(103, 232, 249, 0.1);
}

@media (max-width: 640px) {
  body::before {
    background-size: 48px 48px;
  }
}

