import { NextRequest, NextResponse } from "next/server";

import {
  hasTravelResearchAccess,
  runStructuredWebResearch,
} from "@/lib/travel/openai";
import {
  buildHousingResearchPrompt,
  buildTicketResearchPrompt,
} from "@/lib/travel/prompts";
import {
  housingResearchSchema,
  ticketResearchSchema,
} from "@/lib/travel/schema";
import {
  CABIN_OPTIONS,
  FLEXIBILITY_OPTIONS,
  STAY_OPTIONS,
  type HousingResearch,
  type TicketResearch,
  type TravelResearchInput,
} from "@/lib/travel/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function clampInteger(value: unknown, fallback: number, min: number, max: number) {
  const parsed =
    typeof value === "number"
      ? value
      : typeof value === "string"
        ? Number.parseInt(value, 10)
        : Number.NaN;

  if (!Number.isFinite(parsed)) {
    return fallback;
  }

  return Math.min(max, Math.max(min, parsed));
}

function parseInput(payload: unknown): TravelResearchInput | null {
  if (!payload || typeof payload !== "object") {
    return null;
  }

  const body = payload as Record<string, unknown>;

  if (!isNonEmptyString(body.origin) || !isNonEmptyString(body.destination)) {
    return null;
  }

  if (!isNonEmptyString(body.travelWindow)) {
    return null;
  }

  const flexibility = FLEXIBILITY_OPTIONS.includes(
    body.flexibility as (typeof FLEXIBILITY_OPTIONS)[number],
  )
    ? (body.flexibility as TravelResearchInput["flexibility"])
    : "medium";

  const cabinClass = CABIN_OPTIONS.includes(
    body.cabinClass as (typeof CABIN_OPTIONS)[number],
  )
    ? (body.cabinClass as TravelResearchInput["cabinClass"])
    : "economy";

  const stayStyle = STAY_OPTIONS.includes(
    body.stayStyle as (typeof STAY_OPTIONS)[number],
  )
    ? (body.stayStyle as TravelResearchInput["stayStyle"])
    : "any";

  return {
    origin: body.origin.trim(),
    destination: body.destination.trim(),
    travelWindow: body.travelWindow.trim(),
    tripLengthNights: clampInteger(body.tripLengthNights, 6, 2, 30),
    adults: clampInteger(body.adults, 2, 1, 8),
    flexibility,
    cabinClass,
    stayStyle,
    notes: isNonEmptyString(body.notes) ? body.notes.trim() : undefined,
  };
}

export async function POST(request: NextRequest) {
  if (!hasTravelResearchAccess()) {
    return NextResponse.json(
      {
        error:
          "Pesquisa de viagem indisponível. Configure OPEN_AI_KEY ou OPENAI_API_KEY para habilitar o fluxo.",
        configured: false,
      },
      { status: 503 },
    );
  }

  const input = parseInput(await request.json().catch(() => null));

  if (!input) {
    return NextResponse.json(
      {
        error:
          "Payload inválido. Envie origem, destino, janela de viagem e preferências básicas.",
        configured: true,
      },
      { status: 400 },
    );
  }

  try {
    const ticketResult = await runStructuredWebResearch<TicketResearch>({
      prompt: buildTicketResearchPrompt(input),
      schemaName: "ticket_research",
      schema: ticketResearchSchema,
    });

    const housingResult = await runStructuredWebResearch<HousingResearch>({
      prompt: buildHousingResearchPrompt(input, ticketResult.data.bestOption),
      schemaName: "housing_research",
      schema: housingResearchSchema,
    });

    return NextResponse.json({
      generatedAt: new Date().toISOString(),
      configured: true,
      request: input,
      ticketResearch: {
        ...ticketResult.data,
        sources: ticketResult.sources,
      },
      housingResearch: {
        ...housingResult.data,
        sources: housingResult.sources,
      },
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Falha inesperada na pesquisa.";

    const status = message.includes("OPEN_AI_KEY") ? 503 : 502;

    return NextResponse.json(
      {
        error: message,
        configured: true,
      },
      { status },
    );
  }
}
