  latestDeparture: string;
  tripLengthNights: string;
  travelers: string;
  budgetNotes: string;
  priorities: string;
  lodgingStyle: string;
};

type ApiError = {
  error?: string;
};

const dateFormatter = new Intl.DateTimeFormat("pt-BR", {
  day: "2-digit",
  month: "short",
});

function toMonthOffset(offset: number) {
  const value = new Date();
  value.setDate(1);
  value.setMonth(value.getMonth() + offset);
  return value.toISOString().slice(0, 7);
}

function initialFormState(): TripFormState {
  return {
    origin: "Sao Paulo (GRU)",
    destination: "Lisboa",
    earliestDeparture: toMonthOffset(1),
    latestDeparture: toMonthOffset(6),
    tripLengthNights: "7",
    travelers: "2 adultos",
    budgetNotes: "Prioridade total para custo-beneficio, mesmo com horarios menos nobres.",
    priorities: "Datas baratas, companhias confiaveis e bairros walkable.",
    lodgingStyle: "Apartamento ou hotel boutique com boa localizacao.",
  };
}

function formatDate(value: string) {
  const parsed = new Date(`${value}T00:00:00`);
  return Number.isNaN(parsed.getTime()) ? value : dateFormatter.format(parsed);
}

function formatWindow(option: TicketOption) {
  return `${formatDate(option.travelWindow.departureStart)} - ${formatDate(option.travelWindow.departureEnd)} / volta ${formatDate(option.travelWindow.returnStart)} - ${formatDate(option.travelWindow.returnEnd)}`;
}

