export function TripPlanner() {
  const [form, setForm] = useState<TripFormState>(initialFormState);
  const [result, setResult] = useState<TripResearchResponse | null>(null);
  const [error, setError] = useState<string>("");
  const [isPending, startTransition] = useTransition();

  function updateField<K extends keyof TripFormState>(field: K, value: TripFormState[K]) {
    setForm((current) => ({
      ...current,
      [field]: value,
    }));
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");

    startTransition(() => {
      void (async () => {
        const response = await fetch("/api/trip-research", {
          method: "POST",
          headers: {
            "content-type": "application/json",
          },
          body: JSON.stringify({
            ...form,
            tripLengthNights: Number.parseInt(form.tripLengthNights, 10),
          }),
        });

        const payload = (await response.json()) as TripResearchResponse | ApiError;

        if (!response.ok) {
          setResult(null);
          setError(payload.error ?? "Nao foi possivel concluir a pesquisa.");
          return;
        }

        setResult(payload as TripResearchResponse);
      })().catch(() => {

  if (!featuredTicket) {
    throw new TripResearchError(
      "Ticket research did not return any usable options.",
      502,
      "invalid_response",
    );
  }

  const warnings = [...ticketResearch.caveats];
  let housingResearch: HousingResearch | null = null;

  try {
    housingResearch = await researchHousing(brief, featuredTicket);
    warnings.push(...housingResearch.caveats);
  } catch (error) {
    if (error instanceof TripResearchError) {
      warnings.push(`Housing research unavailable: ${error.message}`);
    } else {
      warnings.push("Housing research unavailable for the selected ticket window.");
    }
  }

  return {
    generatedAt: new Date().toISOString(),
    brief,
    ticketResearch,
    featuredTicket,
    housingResearch,
    warnings,
  };
}

