export type ConfidenceLevel = "high" | "medium" | "low";

export type TripResearchRequest = {
  origin: string;
  destination: string;
  earliestDepartureMonth?: string;
  latestDepartureMonth?: string;
  tripLengthNights: number;
  cabinClass?: string;
