  stayWindow: {
    checkIn: DateWindow;
    checkOut: DateWindow;
    nights: number;
  };
  options: HousingOption[];
  caveats: string[];
};

export type TripResearchResponse = {
  generatedAt: string;
  brief: TripResearchRequest;
  ticketResearch: TicketResearch;
  featuredTicket: TicketResearchOption;
  housingResearch: HousingResearch | null;
  warnings: string[];
};

