  style: "currency",
  currency: "BRL",
});

function statusLabel(status: SearchResponse["providers"][number]["status"]) {
  switch (status) {
    case "ok":
      return "Coletando";
    case "empty":
      return "Sem ofertas";
    case "not_configured":
      return "Aguardando pitchlabs";
    case "error":
      return "Falhou";
    default:
      return "Parcial";
