}

function statusTone(status: SearchResponse["providers"][number]["status"]) {
  switch (status) {
    case "ok":
      return "border-[var(--emerald-400)]/30 bg-[var(--emerald-400)]/12 text-[var(--emerald-100)]";
    case "not_configured":
      return "border-[var(--amber-400)]/30 bg-[var(--amber-400)]/12 text-[var(--amber-50)]";
    case "error":
      return "border-[var(--rose-400)]/30 bg-[var(--rose-400)]/12 text-[var(--rose-50)]";
    default:
