export const FLEXIBILITY_OPTIONS = ["low", "medium", "high"] as const;
export const CABIN_OPTIONS = [
  "economy",
  "premium_economy",
  "business",
] as const;
export const STAY_OPTIONS = ["hotel", "apartment", "boutique", "any"] as const;
export const CONFIDENCE_OPTIONS = ["low", "medium", "high"] as const;

export type Flexibility = (typeof FLEXIBILITY_OPTIONS)[number];
export type CabinClass = (typeof CABIN_OPTIONS)[number];
export type StayStyle = (typeof STAY_OPTIONS)[number];
export type Confidence = (typeof CONFIDENCE_OPTIONS)[number];

export type TravelResearchInput = {
  origin: string;
  destination: string;
  travelWindow: string;
  tripLengthNights: number;
  adults: number;
  flexibility: Flexibility;
  cabinClass: CabinClass;
  stayStyle: StayStyle;
  notes?: string;
};

export type ResearchSource = {
  title: string;
  url: string;
  domain: string;
};

export type TicketDealOption = {
  label: string;
  airline: string;
  departureDate: string;
  returnDate: string;
  estimatedPrice: string;
  bookingChannel: string;
  whyItWins: string;
  tradeoffs: string;
};

export type TicketResearch = {
  summary: string;
  priceOutlook: string;
  bookingTiming: string;
  confidence: Confidence;
  tactics: string[];
  warnings: string[];
  bestOption: TicketDealOption;
  alternatives: TicketDealOption[];
  sources: ResearchSource[];
};

export type HousingAreaOption = {
  area: string;
  stayType: string;
  nightlyRange: string;
  whyStayHere: string;
  cautions: string;
};

export type HousingResearch = {
  summary: string;
  nightlyOutlook: string;
  bookingTiming: string;
  tactics: string[];
  warnings: string[];
  bestArea: HousingAreaOption;
  alternatives: HousingAreaOption[];
  sources: ResearchSource[];
};

export type TravelResearchResponse = {
  generatedAt: string;
  request: TravelResearchInput;
  ticketResearch: TicketResearch;
  housingResearch: HousingResearch;
};

import type { ResearchSource } from "@/lib/travel/types";

const OPENAI_API_URL = "https://api.openai.com/v1/responses";

type StructuredResearchParams = {
  prompt: string;
  schemaName: string;
  schema: Record<string, unknown>;
};

type StructuredResearchResult<T> = {
  data: T;
  sources: ResearchSource[];
};

function getApiKey() {
  return process.env.OPEN_AI_KEY ?? process.env.OPENAI_API_KEY ?? "";
}

function getModel() {
  return process.env.OPENAI_MODEL ?? "gpt-5-mini";
}

function findResponseText(payload: Record<string, unknown>) {
  if (typeof payload.output_text === "string" && payload.output_text.trim()) {
    return payload.output_text.trim();
  }

  const output = Array.isArray(payload.output) ? payload.output : [];

  for (const item of output) {
    if (!item || typeof item !== "object") {
      continue;
    }

    const message = item as {
      type?: string;
      content?: Array<{ text?: string }>;
    };

    if (message.type !== "message" || !Array.isArray(message.content)) {
      continue;
    }

    for (const contentItem of message.content) {
      if (typeof contentItem?.text === "string" && contentItem.text.trim()) {
        return contentItem.text.trim();
      }
    }
  }

  return "";
}

function safeDomain(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

function extractSources(payload: Record<string, unknown>): ResearchSource[] {
  const seen = new Map<string, ResearchSource>();
  const output = Array.isArray(payload.output) ? payload.output : [];

  const addSource = (raw: unknown) => {
    if (!raw || typeof raw !== "object") {
      return;
    }

    const source = raw as {
      title?: unknown;
      url?: unknown;
    };

    if (typeof source.url !== "string" || !source.url) {
      return;
    }

    if (seen.has(source.url)) {
      return;
    }

    seen.set(source.url, {
      title:
