export function buildTicketResearchPrompt(input: TravelResearchInput) {
  return `
Você é um estrategista sênior de viagens.

Use busca web ao vivo para encontrar as melhores oportunidades de passagens para a viagem abaixo. Priorize custo-benefício real, não apenas preço bruto: avalie sazonalidade, companhias aéreas, aeroportos alternativos, promoções sazonais, regras de bagagem, conexões e compra direta vs OTA.

